package main
import("encoding/json";"fmt";"os";"reflect";"github.com/alekpopovic/orch/internal/scheduler";"github.com/alekpopovic/orch/pkg/types")
func main(){const Mi=int64(1024*1024);port:=[]types.Port{{Protocol:types.PortTCP,ContainerPort:80,PublishedPort:31080}};svc:=types.Service{ID:"atlas",Spec:types.ServiceSpec{Name:"atlas-api",Image:"nginx:1.27-alpine",ResourceRequirements:types.ResourceRequirements{Requests:types.Resources{CPU:400,Memory:128*Mi}},Ports:port}};other:=types.Service{ID:"other",Spec:types.ServiceSpec{Name:"other",Image:"nginx",ResourceRequirements:types.ResourceRequirements{Requests:types.Resources{CPU:100,Memory:64*Mi}},Ports:port}};nodes:=[]types.Node{{ID:"a",Status:types.NodeOffline,Allocatable:types.Resources{CPU:4000,Memory:4096*Mi}},{ID:"b",Status:types.NodeReady,Allocatable:types.Resources{CPU:1000,Memory:512*Mi}},{ID:"c",Status:types.NodeReady,Allocatable:types.Resources{CPU:1000,Memory:256*Mi}}};tasks:=[]types.Task{{ID:"atlas-01",ServiceID:"atlas",ActualStatus:types.TaskPending},{ID:"atlas-02",ServiceID:"atlas",ActualStatus:types.TaskPending}};running:=[]types.Task{{ID:"occupied-b",ServiceID:"other",NodeID:"b",DesiredStatus:types.TaskRunning,ActualStatus:types.TaskRunning,Ports:port}};input:=scheduler.PlanInput{Nodes:nodes,PendingTasks:tasks,RunningTasks:running,Services:map[types.ServiceID]types.Service{"atlas":svc,"other":other}};a:=scheduler.Plan(input);if len(a)!=1||a[0].TaskID!="atlas-01"||a[0].NodeID!="c"||a[0].Ports[0].PublishedPort!=31080{panic(fmt.Sprintf("unexpected assignment %#v",a))};input.Nodes=[]types.Node{nodes[2],nodes[0],nodes[1]};input.PendingTasks=[]types.Task{tasks[1],tasks[0]};if !reflect.DeepEqual(a,scheduler.Plan(input)){panic("input order changed deterministic result")};json.NewEncoder(os.Stdout).Encode(map[string]any{"status":"passed","assignments":a,"unassigned_task":"atlas-02","reason_by_inspected_algorithm":"a offline; b fixed port occupied; c fixed port reserved after first assignment","input_permutation_invariant":true,"docker_or_database":"not_used"})}
